# owner: platform
"""Absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from datetime import date


def _check_owner(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id} given "
                f"with student {student.student_id}"
            )


def _absent_days(marks: List[Mark]) -> List[date]:
    days = {m.day for m in marks if m.status == "absent"}
    return sorted(days)


def build_absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Short notice naming the student and the days missed.

    Raises ValueError if a mark belongs to another student or
    if there are no absences.
    """
    marks = list(marks)
    _check_owner(student, marks)
    days = _absent_days(marks)
    if not days:
        raise ValueError("no absences to write a notice about")
    return _compose(student, days)


def _compose(student: Student, days: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    unit = "day" if count == 1 else "days"
    dates = ", ".join(item.isoformat() for item in days)
    return (
        f"{name} missed {count} {unit} of school.\n"
        f"Dates absent: {dates}\n"
    )
EOF
cat > tests/test_notices.py <<'EOF'
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import build_absence_notice

PUPIL = Student("s1", "Lovelace", "Ada", "A")


def mark(day, status="absent", who="s1"):
    return Mark(who, day, status)


class NoticeTests(unittest.TestCase):
    def test_lists_absences_in_order(self):
        marks = [
            mark(date(2026, 9, 9)),
            mark(date(2026, 9, 2), "present"),
            mark(date(2026, 9, 3)),
        ]
        text = build_absence_notice(PUPIL, marks)
        self.assertIn("Ada Lovelace missed 2 days", text)
        self.assertIn("2026-09-03, 2026-09-09", text)

    def test_single_day(self):
        text = build_absence_notice(
            PUPIL, [mark(date(2026, 9, 3))]
        )
        self.assertIn("missed 1 day ", text)

    def test_other_student(self):
        marks = [mark(date(2026, 9, 3), who="s2")]
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, marks)

    def test_no_absences(self):
        marks = [mark(date(2026, 9, 3), "late")]
        with self.assertRaises(ValueError):
            build_absence_notice(PUPIL, marks)
